// Pack snapshots are generated by the same target and checked without weakening sandbox imports.
import assert from 'node:assert/strict';
import { cpSync, copyFileSync, symlinkSync, mkdtempSync, readFileSync, rmSync, writeFileSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import * as vocabulary from '../contracts/generated/vocabulary.ts';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
import { test } from 'node:test';
import { drift, packVocabularyFiles, PACK_VOCABULARY_TARGETS, write } from './gen-contracts.ts';


const RESOURCE_SOURCE='packs/workflow/case-review/tables/resource-tags.json';
function copyResourceSource(root:string):void {
  const from=fileURLToPath(new URL('../'+RESOURCE_SOURCE,import.meta.url));
  const into=join(root,RESOURCE_SOURCE);mkdirSync(join(root,'packs/workflow/case-review/tables'),{recursive:true});copyFileSync(from,into);
}

test('pack vocabulary targets contain only their required axes and deterministic generated bytes', async () => {
  const root = fileURLToPath(new URL('../', import.meta.url));
  const files = packVocabularyFiles(root);
  assert.equal(Object.keys(files).length, Object.keys(PACK_VOCABULARY_TARGETS).length+5);
  const famx='packs/product/famx/functions/generated/vocabulary.ts';
  assert.ok(files[famx]);
  assert.deepEqual(PACK_VOCABULARY_TARGETS[famx],{axes:['applicability_field','declaration_status','judgment_status','type_declaration_status','command_parse_status','reason','release_status'],labels:true,resourceTags:true});
  for (const [path, text] of Object.entries(files)) {
    if(path.endsWith('.json')){assert.equal(text,readFileSync(join(root,RESOURCE_SOURCE),'utf8'));continue;}
    assert.match(text, /^\/\/ 生成物，勿手改/);
    if (PACK_VOCABULARY_TARGETS[path].labels) continue;
    const snapshot = await import(pathToFileURL(join(root, path)).href);
    for (const name of Object.keys(snapshot)) assert.deepEqual(snapshot[name], vocabulary[name as keyof typeof vocabulary]);
    if (path.includes('regression-scope') || path.includes('maintenance-sweep')) {
      assert.match(text, /export const ENTRY_KIND =/);
      assert.match(text, /export const CHANGE_KIND =/);
      assert.match(text, /export const CHANGE_KIND_LABEL:/);
      assert.ok(!text.includes('export const MEASURE ='));
    } else {
      assert.match(text, /export const MEASURE =/);
      assert.ok(!text.includes('export const ENTRY_KIND ='));
    }
  }
  assert.deepEqual(files, packVocabularyFiles(root));
});

test('the generator detects missing, edited and model-stale pack snapshots and repairs them', t => {
  const root = mkdtempSync(join(tmpdir(), 'circle-hub-pack-vocabulary-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  mkdirSync(join(root, 'contracts'), { recursive: true });
  const source = JSON.parse(readFileSync(new URL('../contracts/model.json', import.meta.url), 'utf8'));
  writeFileSync(join(root, 'contracts/model.json'), JSON.stringify(source));
  copyResourceSource(root);
  const expected = packVocabularyFiles(root);
  assert.equal(drift(root, {}, expected).length, Object.keys(expected).length);
  write(root, {}, expected);
  assert.deepEqual(drift(root, {}, expected), []);
  const first = Object.keys(expected).find(path=>path.endsWith('.ts'))!;
  writeFileSync(join(root, first), expected[first] + '// changed\n');
  assert.ok(drift(root, {}, expected).some(p => p.includes(first)));
  write(root, {}, expected);
  source.vocabulary.find((a: { axis: string }) => a.axis === 'measure').values.push({ code: 'synthetic_added', label: '合成新增' });
  writeFileSync(join(root, 'contracts/model.json'), JSON.stringify(source));
  const unchanged = packVocabularyFiles(root);
  assert.deepEqual(unchanged, expected, 'measure changes must not rewrite ID-range consumers');
  source.vocabulary.find((a: { axis: string }) => a.axis === 'change_kind').values.push({ code: 'synthetic_change', label: '合成变更' });
  writeFileSync(join(root, 'contracts/model.json'), JSON.stringify(source));
  const updated = packVocabularyFiles(root);
  assert.equal(drift(root, {}, updated).length, 2);
  write(root, {}, updated);
  assert.deepEqual(drift(root, {}, updated), []);
  assert.ok(readFileSync(join(root, first), 'utf8').includes('生成物，勿手改'));
  source.vocabulary.find((a:{axis:string})=>a.axis==='applicability_field').values.push({code:'synthetic_applicability',label:'合成字段'});
  writeFileSync(join(root,'contracts/model.json'),JSON.stringify(source));
  const applicability=packVocabularyFiles(root);
  const applicabilityDrift=drift(root,{},applicability);
  assert.equal(applicabilityDrift.length,1);
  assert.ok(applicabilityDrift[0].includes('packs/product/famx/functions/generated/vocabulary.ts'));
  for(const path of Object.keys(updated).filter(path=>!path.includes('/famx/')))assert.equal(applicability[path],updated[path]);

});


test('the CLI --check includes every pack snapshot in its drift verdict', t => {
  const root = mkdtempSync(join(tmpdir(), 'circle-hub-pack-vocabulary-cli-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const repo = fileURLToPath(new URL('../', import.meta.url));
  cpSync(join(repo, 'contracts'), join(root, 'contracts'), { recursive: true });
  mkdirSync(join(root, 'tools'));
  copyFileSync(join(repo, 'tools/gen-contracts.ts'), join(root, 'tools/gen-contracts.ts'));
  copyFileSync(join(repo, 'tools/slot-schema.ts'), join(root, 'tools/slot-schema.ts'));
  symlinkSync(join(repo, 'node_modules'), join(root, 'node_modules'), 'dir');
  copyResourceSource(root);
  const run = (...args: string[]) => spawnSync(process.execPath, [join(root, 'tools/gen-contracts.ts'), ...args], { encoding: 'utf8', cwd: root });
  assert.equal(run().status, 0);
  assert.equal(run('--check').status, 0);
  const files = packVocabularyFiles(root);
  for (const [path, content] of Object.entries(files)) {
    writeFileSync(join(root, path), content + '// drift\n');
    const drifted = run('--check');
    assert.equal(drifted.status, 1);
    assert.ok(drifted.stderr.includes(path), drifted.stderr);
    writeFileSync(join(root, path), content);
  }
  assert.equal(run('--check').status, 0);
});

test('registered label snapshots expose generated labels guards and labelOf without changing legacy consumers', async t => {
  const repo=fileURLToPath(new URL('../',import.meta.url));const root=mkdtempSync(join(tmpdir(),'pack-labels-'));t.after(()=>rmSync(root,{recursive:true,force:true}));
  mkdirSync(join(root,'contracts'));const model=JSON.parse(readFileSync(join(repo,'contracts/model.json'),'utf8'));writeFileSync(join(root,'contracts/model.json'),JSON.stringify(model));
  copyResourceSource(root);
  const path='packs/workflow/case-review-report/functions/generated/vocabulary.ts';const files=packVocabularyFiles(root);
  assert.ok(files[path],'the registered consumer must get a package local runtime vocabulary');
  for(const legacy of ['maintenance-sweep','regression-scope']){const file=`packs/workflow/${legacy}/functions/generated/vocabulary.ts`;assert.equal(files[file],readFileSync(join(repo,file),'utf8'));}
  write(root,{},files);const generated=await import(pathToFileURL(join(root,path)).href);
  for(const axis of ['requirement_status','reason','static_terminal','dynamic_terminal','unsatisfied_reason','layer']){
    const source=model.vocabulary.find((v:any)=>v.axis===axis);const type=axis.split('_').map(v=>v[0].toUpperCase()+v.slice(1)).join('');
    for(const value of source.values){assert.equal(generated.labelOf(axis,value.code),value.label);assert.equal(generated['is'+type](value.code),true);}
    for(const value of [undefined,null,1,{},'synthetic-invalid'])assert.equal(generated['is'+type](value),false);
  }
  model.vocabulary.find((v:any)=>v.axis==='reason').values[0].label='合成标签变更';writeFileSync(join(root,'contracts/model.json'),JSON.stringify(model));
  const changed=packVocabularyFiles(root);
  const affected=Object.keys(PACK_VOCABULARY_TARGETS).filter(file=>PACK_VOCABULARY_TARGETS[file].axes.includes('reason')).sort();
  assert.ok(affected.includes(path));
  assert.deepEqual(Object.keys(files).filter(file=>changed[file]!==files[file]).sort(),affected);
  const drifted=drift(root,{},changed).map(line=>line.replace(/^out of date: /,'').replace(/ \(first difference at line \d+\)$/,'')).sort();
  assert.deepEqual(drifted,affected);
  assert.deepEqual(changed,packVocabularyFiles(root));
});

test('resource declarations generate exact business values without adding a core business axis',async t=>{
 const root=mkdtempSync(join(tmpdir(),'resource-vocabulary-'));t.after(()=>rmSync(root,{recursive:true,force:true}));mkdirSync(join(root,'contracts'));
 const repo=fileURLToPath(new URL('../',import.meta.url));writeFileSync(join(root,'contracts/model.json'),readFileSync(join(repo,'contracts/model.json')));copyResourceSource(root);
 const files=packVocabularyFiles(root);write(root,{},files);
 const snapshot=await import(pathToFileURL(join(root,'packs/workflow/case-review/functions/generated/vocabulary.ts')).href);
 const table=JSON.parse(readFileSync(join(root,RESOURCE_SOURCE),'utf8'));
 assert.deepEqual(snapshot.RESOURCE_TAGS,table.tags);
 for(const row of table.tags){assert.equal(snapshot.declaredResourceTag(row.text)?.id,row.id);assert.equal(snapshot.declaredResourceTag(row.text+' '),null);}
 assert.deepEqual(snapshot.declareResourceTags(['negative']).negative,true);
 assert.equal(snapshot.declareResourceTags(['Negative']).negative,null);
 assert.equal(snapshot.declareResourceTags(['functional','unknown']).negative,null);
 assert.equal(snapshot.declareResourceTags(['R2ADD']).status,'undeclared');
 assert.equal(snapshot.declareResourceTags([]).negative,null);
 assert.equal(snapshot.declareResourceTags({}).valid,false);
 const changed=structuredClone(table);changed.tags[1].text=changed.tags[0].text;writeFileSync(join(root,RESOURCE_SOURCE),JSON.stringify(changed));
 assert.throws(()=>packVocabularyFiles(root),/unique/);
 const model=JSON.parse(readFileSync(join(root,'contracts/model.json'),'utf8'));assert.ok(!model.vocabulary.some((axis:{axis:string})=>axis.axis==='test_type'));
});
